        this.nameKey = "~merged~" + id;
        this.contact = null;
        this.patronIds.clear();
        this.holds.clear();
    }

    /**
     * Move the person to another sheet: they keep their grades, terms, contact, aliases and
     * statements, but name no patrons and have no holds. They show the sheet they came from, and
     * keep the other sheet's today they arrived on.
     */
    public void transferTo(String sheetId, LocalDate arrivedOn) {
        this.originSheetId = this.sheetId;
        this.arrivedOn = arrivedOn;
        this.sheetId = sheetId;
        this.patronIds.clear();
        this.holds.clear();
    }

    /** No longer name this person as a patron; false when they were not one. */
    public boolean removePatron(Long patronId) {
        return patronIds.remove(patronId);
    }

    /** Name another person as a patron; false when they already are one. */
    public boolean addPatron(Long patronId) {
        if (patronIds.contains(patronId)) {
            return false;
        }
        return patronIds.add(patronId);
    }
}
-- A person can be retired from a date: no claim dated after it can be added for them. Null while
-- they are not retired. A retired person's claims keep counting in every total.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no
-- live total (their own, the sheet's, a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- A person's grade is dated: the grade on the person row is the first they were given, applying from
-- the beginning of time; each later grade is recorded here from its date, one per date, and holds
-- from that date until the next.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
